package dev.gamersclt.batcaverna.nativeapp;
import android.app.Dialog;
import android.content.Context;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
/** Shared native modal with one close control and a bounded, scrollable body. */
final class NativeSheet {
 final Dialog dialog;final LinearLayout body,footer,controls;private final LinearLayout root;private TextView closeControl;
 NativeSheet(Context c,String title){dialog=new Dialog(c);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);root=new LinearLayout(c){protected void onMeasure(int width,int height){int cap=Math.round(windowSize(c)[1]*.9f);if(MeasureSpec.getMode(height)!=MeasureSpec.UNSPECIFIED)cap=Math.min(cap,MeasureSpec.getSize(height));super.onMeasure(width,MeasureSpec.makeMeasureSpec(cap,MeasureSpec.AT_MOST));}};root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(c,16),dp(c,12),dp(c,16),dp(c,16));root.setBackground(AppStyle.shape(root,0xff151c27,24));LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);TextView label=text(c,title,20,0xfff3f4f8);label.setTypeface(null,Typeface.BOLD);header.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView close=text(c,"×",28,0xffbdadff);closeControl=close;close.setGravity(Gravity.CENTER);close.setContentDescription("Fechar janela");close.setOnClickListener(v->dialog.dismiss());header.addView(close,new LinearLayout.LayoutParams(dp(c,48),dp(c,48)));root.addView(header);controls=new LinearLayout(c);controls.setOrientation(LinearLayout.VERTICAL);controls.setVisibility(View.GONE);root.addView(controls,new LinearLayout.LayoutParams(-1,-2));
  ScrollView scroll=new ScrollView(c);scroll.setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,-2,1));footer=new LinearLayout(c);footer.setOrientation(LinearLayout.VERTICAL);footer.setVisibility(View.GONE);root.addView(footer,new LinearLayout.LayoutParams(-1,-2));dialog.setContentView(root);dialog.setOnShowListener(d->{dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(windowSize(c)[0]-dp(c,24),dp(c,720)),WindowManager.LayoutParams.WRAP_CONTENT);dialog.getWindow().setDimAmount(.68f);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);});
 }
 void show(){dialog.show();}
 void busy(boolean active){dialog.setCancelable(!active);if(closeControl!=null)closeControl.setEnabled(!active);}
 static int[] windowSize(Context c){if(c instanceof android.app.Activity){android.app.Activity a=(android.app.Activity)c;android.view.View decor=a.getWindow().getDecorView();if(android.os.Build.VERSION.SDK_INT>=30){android.view.WindowMetrics m=a.getWindowManager().getCurrentWindowMetrics();android.graphics.Insets i=m.getWindowInsets().getInsetsIgnoringVisibility(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());return new int[]{m.getBounds().width()-i.left-i.right,m.getBounds().height()-i.top-i.bottom};}android.graphics.Rect frame=new android.graphics.Rect();decor.getWindowVisibleDisplayFrame(frame);if(frame.width()>0&&frame.height()>0)return new int[]{frame.width(),frame.height()};}return new int[]{c.getResources().getDisplayMetrics().widthPixels,dp(c,c.getResources().getConfiguration().screenHeightDp)};}
 static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 static TextView text(Context c,String value,int size,int color){TextView v=new TextView(c);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(c,6),0,dp(c,6));return v;}
 static EditText input(Context c,String hint,int max){EditText e=new EditText(c);e.setHint(hint);e.setTextSize(14);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});AppStyle.input(e);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(c,6),0,dp(c,8));e.setLayoutParams(p);return e;}
 static Spinner options(Context c,String[] values){Spinner s=new Spinner(c);s.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_item,values){public View getView(int pos,View old,ViewGroup parent){TextView t=(TextView)super.getView(pos,old,parent);t.setTextColor(0xfff3f4f8);t.setPadding(dp(c,12),dp(c,12),dp(c,12),dp(c,12));return t;}public View getDropDownView(int pos,View old,ViewGroup parent){TextView t=(TextView)super.getDropDownView(pos,old,parent);t.setTextColor(0xfff3f4f8);t.setBackgroundColor(0xff242d3a);t.setPadding(dp(c,14),dp(c,16),dp(c,14),dp(c,16));return t;}});s.setBackground(AppStyle.shape(s,0xff242d3a,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(c,ResponsivePolicy.controlHeight(c.getResources().getConfiguration().fontScale)));lp.setMargins(0,dp(c,6),0,dp(c,10));s.setLayoutParams(lp);return s;}
}
